contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 limit, uint256 donationAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donationAmount)); require(donationAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= donationAmount);
        // Before opening to the public, donate must revert regardless of amount.
        bool donateReverted;
        c.donate{value: donationAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { donateReverted = true; } else { donateReverted = false; }
        // Owner-only adjustment must succeed and set the exact limit.
        c.AdjustBetAmounts(limit); if (__ESBMC_reverted()) return;
        uint256 newLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        assert(donateReverted && newLimit == limit);
    }
    receive() external payable {}
}

